Two Sum (LeetCode 1): use a hash map from value to index. For each element, check whether `target - nums[i]` is already in the map; if so, return the pair, otherwise store the current value and index.

```csharp
using System.Collections.Generic;

public class Solution {
    public int[] TwoSum(int[] nums, int target) {
        var seen = new Dictionary<int, int>(nums.Length);
        for (int i = 0; i < nums.Length; i++) {
            long complement = (long)target - nums[i];
            if (complement >= int.MinValue && complement <= int.MaxValue
                && seen.TryGetValue((int)complement, out int j))
                return new[] { j, i };
            seen[nums[i]] = i;
        }
        return System.Array.Empty<int>();
    }
}
```

